def _build(tree):
    if not tree or tree[0] is None:
        return None
    nodes = [None if v is None else {'val': v, 'left': None, 'right': None} for v in tree]
    kids = iter(range(1, len(nodes)))
    for node in nodes:
        if node is None:
            continue
        for side in ('left', 'right'):
            idx = next(kids, None)
            if idx is not None and idx < len(nodes) and nodes[idx] is not None:
                node[side] = nodes[idx]
    return nodes[0]


def is_symmetric(tree):
    root = _build(tree)
    if root is None:
        return True

    def mirror(a, b):
        if a is None and b is None:
            return True
        if a is None or b is None:
            return False
        if a['val'] != b['val']:
            return False
        return mirror(a['left'], b['right']) and mirror(a['right'], b['left'])

    return mirror(root['left'], root['right'])
